// Scratch tool (not part of the product): extracts embedded images from a PDF so the
// spec diagrams (use case, sequence, class, architecture) can be viewed. Usage:
//   node extract-images.js <input.pdf> <outDir>
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const [, , input, outDir] = process.argv;
const buf = fs.readFileSync(input);
const bin = buf.toString('latin1');
fs.mkdirSync(outDir, { recursive: true });

// CRC32 for PNG chunks
const crcTable = new Int32Array(256).map((_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c;
});
function crc32(b) {
  let c = -1;
  for (let i = 0; i < b.length; i++) c = crcTable[(c ^ b[i]) & 0xff] ^ (c >>> 8);
  return (c ^ -1) >>> 0;
}
function chunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const td = Buffer.concat([Buffer.from(type, 'latin1'), data]);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td));
  return Buffer.concat([len, td, crc]);
}
function png(width, height, channels, raw) {
  const colorType = channels === 1 ? 0 : channels === 3 ? 2 : 6;
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0); ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; ihdr[9] = colorType; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
  const stride = width * channels;
  const rows = Buffer.alloc((stride + 1) * height);
  for (let y = 0; y < height; y++) {
    rows[y * (stride + 1)] = 0;
    raw.copy(rows, y * (stride + 1) + 1, y * stride, (y + 1) * stride);
  }
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(rows)), chunk('IEND', Buffer.alloc(0)),
  ]);
}

const objRe = /(\d+)\s+0\s+obj\s*<<([\s\S]*?)>>\s*stream\r?\n/g;
let m; let count = 0;
while ((m = objRe.exec(bin))) {
  const dict = m[2];
  if (!/\/Subtype\s*\/Image/.test(dict)) continue;
  const lenM = dict.match(/\/Length\s+(\d+)(\s+0\s+R)?/);
  let len;
  if (lenM && !lenM[2]) len = parseInt(lenM[1], 10);
  else {
    const endIdx = bin.indexOf('endstream', m.index + m[0].length);
    len = endIdx - (m.index + m[0].length);
  }
  const start = m.index + m[0].length;
  const data = buf.subarray(start, start + len);
  const w = +(dict.match(/\/Width\s+(\d+)/) || [])[1];
  const h = +(dict.match(/\/Height\s+(\d+)/) || [])[1];
  const name = `obj${m[1]}_${w}x${h}`;
  try {
    if (/DCTDecode/.test(dict)) {
      fs.writeFileSync(path.join(outDir, name + '.jpg'), data);
    } else if (/FlateDecode/.test(dict)) {
      const raw = zlib.inflateSync(data);
      const bpc = +(dict.match(/\/BitsPerComponent\s+(\d+)/) || [0, 8])[1];
      if (bpc !== 8) { console.log('skip bpc', name, bpc); continue; }
      const channels = Math.round(raw.length / (w * h));
      if (![1, 3, 4].includes(channels)) { console.log('skip channels', name, channels); continue; }
      fs.writeFileSync(path.join(outDir, name + '.png'), png(w, h, channels, raw));
    } else { console.log('skip filter', name); continue; }
    count++;
    console.log('wrote', name, dict.replace(/\s+/g, ' ').slice(0, 160));
  } catch (e) { console.log('fail', name, e.message); }
}
console.log('images:', count);

