            onDone={() => setEstimate(null)}
          />
        </View>
      ) : null}
    </View>
  );
}

// ---- [Dining menu item] — FR-8 ---------------------------------------------------------------------------------
function DiningMenu({ onSaved, onError }: { onSaved: SavedFn; onError: ErrFn }) {
