        String token = login("dev", DemoDataSeeder.DEMO_PASSWORD, DemoDataSeeder.DEV_SECRET);
        JsonNode me = call(get("/api/auth/me"), token, null, 200);
        return new Account(me.get("userId").asLong(), "dev", DemoDataSeeder.DEV_SECRET, token);
    }

