        assertThat(sum.get("steps").asInt()).isEqualTo(2000);
        assertThat(sum.get("latestHeartRate").asInt()).isEqualTo(95);
    }

    @Test
    void pairingFailureAndUnlinkedDevicesAreRejected() throws Exception {
        Account a = newStudent("devfail");
