        JsonNode r3 = POST("/api/activity/steps", a, Map.of("deviceId", id, "steps", 600), 201);
        assertThat(r3.get("pointsAwarded").isNull()).isTrue();
        assertThat(r3.get("balance").asInt()).isEqualTo(PointsService.STEP_GOAL_POINTS);
    }

