        assertThat(none.get("waterTodayMl").isNull()).isTrue();
        assertThat(none.get("stepsToday").isNull()).isTrue();
        assertThat(none.get("visitsThisWeek").isNull()).isTrue();
        assertThat(none.get("points").isNull()).isTrue();

